    def find_good_partitions(l, r):
        if l == r:
            return [(l, r)]
        i = 0
        while (1 << i) <= r:
            if (1 << i) > l:
                break
            i += 1
        mid = (1 << i)
        partitions = [(l, mid)]
        l, r = mid, r
        while l < r:
            i = 0
            while (1 << i) <= r:
                if (1 << i) > l:
                    break
                i += 1
            mid = (1 << i)
            partitions.append((l, mid))
            l, r = mid, r
        return partitions

