        m, n = len(grid), len(grid[0])
        count = 0

        def is_right_triangle(i1, j1, i2, j2, i3, j3):
            return grid[i1][j1] + grid[i2][j2] + grid[i3][j3] == 3 and (j1 == j2 and i2 == i3) or (i1 == i2 and j1 == j3 and i3 == j2)

        for i1 in range(m):
            for j1 in range(n):
                if grid[i1][j1] == 1:
                    for i2 in range(m):
                        for j2 in range(n):
                            if grid[i2][j2] == 1 and (i1, j1) != (i2, j2):
                                for i3 in range(m):
                                    for j3 in range(n):
                                        if grid[i3][j3] == 1 and (i2, j2) != (i3, j3) and is_right_triangle(i1, j1, i2, j2, i3, j3):
                                            count += 1
        return count
